func countInversions(nums []int) int {
	work := append([]int(nil), nums...)
	buf := make([]int, len(work))
	return sortCount(work, buf, 0, len(work))
}

// sortCount sorts a[lo:hi] in place and returns the inversions it contained.
func sortCount(a, buf []int, lo, hi int) int {
	if hi-lo < 2 {
		return 0
	}
	mid := lo + (hi-lo)/2
	count := sortCount(a, buf, lo, mid) + sortCount(a, buf, mid, hi)
	i, j, k := lo, mid, lo
	for i < mid && j < hi {
		if a[i] <= a[j] {
			buf[k] = a[i]
			i++
		} else {
			count += mid - i
			buf[k] = a[j]
			j++
		}
		k++
	}
	for i < mid {
		buf[k] = a[i]
		i++
		k++
	}
	for j < hi {
		buf[k] = a[j]
		j++
		k++
	}
	copy(a[lo:hi], buf[lo:hi])
	return count
}
